/// <summary>
/// Validate write.
/// </summary>
/// <returns>True or false.</returns>
public boolean validateWrite()
{
    boolean ret = super();

    ret = ret && this.checkConditionValue();

    return ret;
}

/// <summary>
/// Get the related pricing attribute.
/// </summary>
/// <returns>The pricing attribute.</returns>
public GUPIPricingAttribute pricingAttribute()
{
    GUPPricingAttributeLink link = this.priceAttributeLink();

    return GUPPricingAttributeRepository::priceAttribute(
        link.PriceAttributeClassId,
        link.AttributeProviderClassId,
        link.AttributeName, 
        link.TypeName);
}

internal GUPPricingAttributeLink priceAttributeLink()
{
    GUPPricingAttributeLink link;

    select firstonly link where link.RecId == this.ConditionAttribute;

    return link;
}

/// <summary>
/// Validate condition value
/// </summary>
/// <returns>True if condition value is correct; Otherwise false</returns>
internal boolean checkConditionValue()
{
    boolean ret = true;

    if (this.ConditionValue)
    {
        GUPPricingAttributeLink pricingAttributeLink = this.priceAttributeLink();

        if (pricingAttributeLink.PriceAttributeClassId == classNum(GUPPricingAttributeEcoResAttribute))
        {
            EcoResAttributeDefaultValueHelper attributeDefaultValueHelper = new EcoResAttributeDefaultValueHelper(EcoResAttributeType::findByName(pricingAttributeLink.TypeName));
            AttributeDataType attributeDataType = this.pricingAttribute().getDataType();

            if (attributeDataType != AttributeDataType::TrueFalse
                && attributeDataType != AttributeDataType::Reference
                && !attributeDefaultValueHelper.validateDefaultValue(GUPPricingAttributeLink::getEcoResValue(attributeDataType, this.ConditionValue)))
            {
                ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPAttributeValueRangeError", this.ConditionValue, pricingAttributeLink.TypeName));
            }
        }
    }

    return ret;
}

static GUPPricingRuleCondition find(RefRecId    _ruleId,
                                    GUPRefRecId _conditionAttribute,
                                    boolean     _update = false)
{
    GUPPricingRuleCondition gupPricingRuleCondition;

    if (_ruleId && _conditionAttribute)
    {
        if (_update)
        {
            gupPricingRuleCondition.selectForUpdate(_update);
        }

        select firstonly gupPricingRuleCondition
            index hint RuleIdx
                where gupPricingRuleCondition.RuleId == _ruleId
                &&    gupPricingRuleCondition.ConditionAttribute == _conditionAttribute;

    }

    return gupPricingRuleCondition;
}

/// <summary>
/// Modify condition value
/// </summary>
/// <param name = "_name">New value</param>
/// <param name = "_appendValueOnLookup">Append/override value</param>
public void editConditionValue(Name _name, NoYes _appendValueOnLookup = NoYes::No)
{
    if (strCmp(strLRTrim(this.priceAttributeLink().AttributeName), GUPPricingAttributeAllowedValueLookup::NEED_HIERARCHICAL_ATTRIBUTE_NAME) == 0
                && _appendValueOnLookup
                && strLen(this.ConditionValue) > 0)
    {
        boolean categoryAlreadyAdded = false;
        ListEnumerator existingCategoriesListEnumerator = strSplit(this.ConditionValue, ",").getEnumerator();
        while (existingCategoriesListEnumerator.moveNext())
        {
            if (existingCategoriesListEnumerator.current() == _name)
            {
                categoryAlreadyAdded = true;
                break;
            }
        }
        if (!categoryAlreadyAdded)
        {
            this.ConditionValue +=  "," + _name;
        }
    }
    else
    {
        this.ConditionValue = _name;
    }
}
